import { test, expect } from '@playwright/test';
import * as ui from '../support/ui';

test.setTimeout(240_000);
test.describe("tree numbering", () => {
  test("tree numbering", { tag: '@functionality' }, async ({ browser }) => {
    const sheet = ui.sheetId();
    const pg_uma = await ui.userPage(browser, "uma", sheet);
    await ui.loadSheet(pg_uma, `${sheet}-p`);
    await ui.setToday(pg_uma, "2026-03-10");
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "10.00"})).toBe(true);
    const p_pam = ui.must(await ui.addPerson(pg_uma, {"name": "Pam", "grade": "A"}));
    const c_pam_0 = ui.must(await ui.addClaim(pg_uma, p_pam, {"amount": "1.00"}));
    const c_pam_1 = ui.must(await ui.addClaim(pg_uma, p_pam, {"amount": "2.00"}));
    expect(await ui.claimAction(pg_uma, c_pam_0, "open")).toBe(true);
    await ui.loadSheet(pg_uma, sheet);
    await ui.setToday(pg_uma, "2026-03-10");
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "10.00"})).toBe(true);
    const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A"}));
    const c_ada_0 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "10.00"}));
    const c_ada_1 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "20.00"}));
    const c_ada_2 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "30.00"}));
    expect(await ui.claimAction(pg_uma, c_ada_0, "open")).toBe(true);
    await ui.setSetting(pg_uma, "parent", `${sheet}-p`);
    expect(await ui.claimAction(pg_uma, c_ada_1, "open")).toBe(true);
    await ui.loadSheet(pg_uma, `${sheet}-p`);
    expect(await ui.claimAction(pg_uma, c_pam_1, "open")).toBe(true);
    await ui.loadSheet(pg_uma, `${sheet}-c`);
    await ui.setToday(pg_uma, "2026-03-10");
    await ui.setSetting(pg_uma, "parent", `${sheet}`);
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "10.00"})).toBe(true);
    const p_cy = ui.must(await ui.addPerson(pg_uma, {"name": "Cy", "grade": "A"}));
    const c_cy_0 = ui.must(await ui.addClaim(pg_uma, p_cy, {"amount": "3.00"}));
    expect(await ui.claimAction(pg_uma, c_cy_0, "open")).toBe(true);
    await ui.setSetting(pg_uma, "period-numbering-from", "2026-03-01");
    expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-31"})).toBe(true);
    const c_cy_1 = ui.must(await ui.addClaim(pg_uma, p_cy, {"amount": "4.00"}));
    expect(await ui.claimAction(pg_uma, c_cy_1, "open")).toBe(true);
    await ui.refresh(pg_uma);
    await expect(pg_uma.getByTestId("claim-row-" + c_cy_1).getByTestId("claim-number")).toHaveText("P1-1");
    await expect(pg_uma.getByTestId("claim-row-" + c_cy_1).getByTestId("claim-status")).toHaveText("OPEN");
    await expect(pg_uma.getByTestId("claim-row-" + c_cy_0).getByTestId("claim-number")).toHaveText("4");
    await expect(pg_uma.getByTestId("claim-row-" + c_cy_0).getByTestId("claim-status")).toHaveText("OPEN");
    await ui.expectAudit(`${sheet}-c`, [
      `SETTING_CHANGED sheet=${sheet}-c by=uma key=parent value=${sheet}`,
      `RATE_SET sheet=${sheet}-c by=uma grade=A rate=10.00`,
      `PERSON_ADDED sheet=${sheet}-c by=uma name=Cy grade=A`,
      `ROLLUP sheet=${sheet}-c by=uma person=Cy claimed=0.00 due-total=0.00 overdue-total=0.00`,
      `CLAIM_ADDED sheet=${sheet}-c by=uma person=Cy amount=3.00 date=2026-03-10`,
      `CLAIM_OPENED sheet=${sheet}-c by=uma person=Cy amount=3.00 date=2026-03-10 number=4`,
      `ROLLUP sheet=${sheet}-c by=uma person=Cy claimed=3.00 due-total=1.00 overdue-total=0.00`,
      `TOTALS sheet=${sheet}-c by=uma claimed-total=3.00 due-total=1.00 overdue-total=0.00`,
      `SETTING_CHANGED sheet=${sheet}-c by=uma key=period-numbering-from value=2026-03-01`,
      `PERIOD_ADDED sheet=${sheet}-c by=uma period=P1 from=2026-03-01 to=2026-03-31`,
      `CLAIM_ADDED sheet=${sheet}-c by=uma person=Cy amount=4.00 date=2026-03-10`,
      `CLAIM_OPENED sheet=${sheet}-c by=uma person=Cy amount=4.00 date=2026-03-10 number=P1-1`,
      `ROLLUP sheet=${sheet}-c by=uma person=Cy claimed=7.00 due-total=2.00 overdue-total=0.00`,
      `TOTALS sheet=${sheet}-c by=uma claimed-total=7.00 due-total=2.00 overdue-total=0.00`
    ]);
    await ui.loadSheet(pg_uma, sheet);
    expect(await ui.claimAction(pg_uma, c_ada_2, "open")).toBe(true);
    await ui.refresh(pg_uma);
